print("\nMost similar spacer pairs:")
pairs=[]
for i in range(n):
    for j in range(i+1,n):
        d=sum(x!=y for x,y in zip(spacers[i],spacers[j]))
        pairs.append((d,i+1,j+1))
for d,i,j in sorted(pairs)[:5]:
